const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the raw build-graph text into a map of task name -> { name, cost,
 * deps: Set<string> }. Validates every syntactic rule the spec lists for
 * `task` and `dep` lines, then resolves every `dep` reference against the
 * declared tasks, and finally rejects the graph if it contains a cycle.
 *
 * Throws CliError for ordinary validation failures and CycleError when a
 * cycle is found.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const tasks = new Map()
  const depLines = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'task') {
      if (tokens.length !== 3) {
        throw new CliError(`line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, costStr] = tokens
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, { name, cost: parseInt(costStr, 10), deps: new Set() })
    } else if (directive === 'dep') {
      if (tokens.length < 3) {
        throw new CliError(`line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const name = tokens[1]
      const deps = tokens.slice(2)
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNo}: invalid task name ${name}`)
      }
      for (const dep of deps) {
        if (!NAME_RE.test(dep)) {
          throw new CliError(`line ${lineNo}: invalid task name ${dep}`)
        }
      }
      depLines.push({ name, deps, lineNo })
    } else {
      throw new CliError(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const depLine of depLines) {
    if (!tasks.has(depLine.name)) {
      throw new CliError(`unknown task ${depLine.name}`)
    }
    for (const dep of depLine.deps) {
      if (!tasks.has(dep)) {
        throw new CliError(`unknown task ${dep}`)
      }
    }
    const node = tasks.get(depLine.name)
    for (const dep of depLine.deps) {
      node.deps.add(dep)
    }
  }

  return tasks
}
"}

