/**
 * Runs a depth-first search over every task, starting from each task in
 * ascending name order and walking each task's dependencies in ascending
 * name order. Throws CycleError for the first cycle such a search finds:
 * the path from the re-entered task, through the search stack, back to
 * that task.
 */
export function checkForCycle(tasks) {
  const color = new Map() // undefined = white, 1 = gray, 2 = black
  const stack = []
  const names = [...tasks.keys()].sort()

  function visit(name) {
    color.set(name, 1)
    stack.push(name)
    const deps = [...tasks.get(name).deps].sort()
    for (const dep of deps) {
      const state = color.get(dep)
      if (state === 1) {
        const idx = stack.indexOf(dep)
        const cyclePath = stack.slice(idx).concat(dep)
        throw new CycleError(cyclePath)
      }
      if (state !== 2) {
        visit(dep)
      }
    }
    color.set(name, 2)
    stack.pop()
  }

  for (const name of names) {
    if (!color.has(name)) {
      visit(name)
    }
  }
}

/**
 * Computes, for every task, the unlimited-worker start, finish and wave
 * depth: start is the greatest finish of its dependencies (0 when none),
 * finish is start + cost, and depth is 1 + the greatest dependency depth
 * (0 when none). Assumes the graph has no cycle.
 */
export function computeTimings(tasks) {
  const timings = new Map()

  function compute(name) {
    if (timings.has(name)) return timings.get(name)
    const task = tasks.get(name)
    let start = 0
    let depth = 0
    for (const dep of task.deps) {
      const depTiming = compute(dep)
      if (depTiming.finish > start) start = depTiming.finish
      if (depTiming.depth + 1 > depth) depth = depTiming.depth + 1
    }
    const result = { start, finish: start + task.cost, depth }
    timings.set(name, result)
    return result
  }

  for (const name of tasks.keys()) {
    compute(name)
  }

  return timings
}

/**
 * Computes, for every task, the priority used by `pack`: the cost of the
 * longest chain that begins at the task, counting its own cost and then
 * the costs down to any task that nothing depends on (i.e. following the
 * chain of tasks that depend on it).
 */
export function computePriorities(tasks) {
  const successors = new Map()
  for (const name of tasks.keys()) successors.set(name, [])
  for (const [name, task] of tasks) {
    for (const dep of task.deps) {
      successors.get(dep).push(name)
    }
  }

  const priorities = new Map()

  function compute(name) {
    if (priorities.has(name)) return priorities.get(name)
    const task = tasks.get(name)
    let best = 0
