 */

import { readFileSync } from 'node:fs'
import { CliError, CycleError } from './errors.js'
import { parseGraph } from './parser.js'
import { checkForCycle, computeTimings } from './graph.js'
import { pack } from './scheduler.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main() {
  const argv = process.argv.slice(2)
  const args = parseArgs(argv)

  const input = readStdin()
  const tasks = parseGraph(input)
  checkForCycle(tasks)

  const output = []

  if (args.mode === 'waves') {
    const timings = computeTimings(tasks)
    const names = [...tasks.keys()].sort()
    const waves = []
    for (const name of names) {
      const depth = timings.get(name).depth
      if (!waves[depth]) waves[depth] = []
      waves[depth].push(name)
    }
    let total = 0
    for (const t of timings.values()) {
      if (t.finish > total) total = t.finish
    }
    for (let k = 0; k < waves.length; k++) {
      const wave = waves[k] ? waves[k].slice().sort() : []
      output.push(`wave ${k}: ${wave.join(' ')}`)
    }
    output.push(`total ${total}`)
  } else if (args.mode === 'explain') {
    const timings = computeTimings(tasks)
    const names = [...tasks.keys()].sort()
    let total = 0
    for (const t of timings.values()) {
      if (t.finish > total) total = t.finish
    }
    for (const name of names) {
      const t = timings.get(name)
      output.push(`${name} start=${t.start} finish=${t.finish} depth=${t.depth}`)
    }
    output.push(`total ${total}`)
  } else if (args.mode === 'pack') {
    const { workerLogs, makespan } = pack(tasks, args.workers)
    for (let i = 0; i < workerLogs.length; i++) {
      const entries = workerLogs[i].map((e) => `${e.name}@${e.start}-${e.finish}`)
      output.push(`worker ${i}:${entries.length ? ' ' + entries.join(' ') : ''}`)
    }
    output.push(`makespan ${makespan}`)
  }

  process.stdout.write(output.join('\n') + '\n')
}

