  if (err instanceof CycleError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(3)
  } else if (err instanceof CliError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(2)
  } else {
    throw err
  }
}
